import {renderDiagram} from './visual.js?v=20261023-physicscomplete01';
import {cellPairs} from './cell-models.js?v=20261023-physicscomplete01';
const text=(x,y,s,n=16)=>`<text x="${x}" y="${y}" text-anchor="middle" fill="#f8f6f2" font-family="sans-serif" font-size="${n}">${s}</text>`;
export function showCells(kind='voltage',t=null,reveal=false){let art='',title='',sub='',desc='';
if(kind==='voltage'){t??=cellPairs[0];title='Follow the charge';sub=t.left+' / '+t.right+' · '+t.count+' aligned cells';desc='Two different metal electrodes in a shared electrolyte, connected to a voltmeter. Ions carry charge inside; electrons use the metal wire. Controlled illustrative data: Mg/Cu1.6V, Zn/Cu0.8V; electrons leave Mg or Zn toward Cu.';art=`<path d="M95 135V65H345V135" fill="none" stroke="#b7c8d6" stroke-width="4"/><rect x="180" y="40" width="80" height="52" rx="18" fill="#182e44" stroke="#f8f6f2"/>${text(220,72,reveal?t.voltage.toFixed(1)+' V':'V',20)}<path d="M55 140V255H385V140" fill="#b7c8d622" stroke="#b7c8d6" stroke-width="2"/><rect x="85" y="115" width="25" height="105" rx="6" fill="#ed8b78"/><rect x="330" y="115" width="25" height="105" rx="6" fill="#d4dfe7"/>${text(98,105,t.left)}${text(342,105,t.right)}${text(220,200,'Mobile ions in electrolyte',15)}${reveal?text(220,25,t.donor==='left'?'Electrons: left → right':'Electrons: right → left',16):''}${text(220,285,reveal?'Series battery: '+(t.voltage*t.count).toFixed(1)+' V':'Mg/Cu 1.6 V · Zn/Cu 0.8 V',16)}`;
}else if(kind==='equations'){title='Balance atoms and charge';sub=t?.title||'Acidic or alkaline · stated conditions';desc='Fuel-cell electrode map. Hydrogen oxidation at the negative anode releases electrons into the external circuit; oxygen reduction at the positive cathode consumes them. Ions carry charge internally. The overall product is water.';art=`${text(220,30,'Electrons: anode → circuit → cathode',16)}<path d="M100 95V55H340V95" stroke="#ed8b78" stroke-width="4" fill="none"/><rect x="60" y="95" width="80" height="120" rx="20" fill="#ed8b7844" stroke="#ed8b78"/><rect x="300" y="95" width="80" height="120" rx="20" fill="#b7c8d633" stroke="#b7c8d6"/>${text(100,140,'H₂')}${text(100,175,'Oxidation',13)}${text(340,140,'O₂')}${text(340,175,'Reduction',13)}${text(100,240,'− Anode')}${text(340,240,'+ Cathode')}${text(220,195,'Ions',14)}${text(220,285,reveal?'Atoms and charge balanced':'2H₂ + O₂ → 2H₂O',16)}`;
}else{title='Supply fuel. Transfer energy.';sub=t?.title||'Hydrogen + oxygen → water';desc='Hydrogen and oxygen or air enter a fuel cell from external supplies. Electricity leaves through an external circuit and water is the reaction product. Production, storage and transport affect lifecycle impact.';art=`<defs><linearGradient id="cellBody"><stop stop-color="#b7c8d644"/><stop offset="1" stop-color="#ed8b7833"/></linearGradient></defs><rect x="125" y="75" width="190" height="150" rx="25" fill="url(#cellBody)" stroke="#b7c8d6"/><path d="M35 105H120M35 190H120M320 115H410M320 200H410" stroke="#ed8b78" stroke-width="4"/>${text(70,85,'H₂ in',15)}${text(70,170,'O₂ / air',15)}${text(365,95,'Electricity',14)}${text(365,180,'Water out',14)}${text(220,145,'FUEL CELL',18)}${text(220,180,'External supplies',13)}${text(220,270,reveal?'Decision supported by the supplied evidence':'Water at use ≠ zero lifecycle impact',15)}`;}
renderDiagram(title,sub,`<svg class="lab-svg" viewBox="0 0 440 310" role="img" aria-label="${desc}">${art}</svg><p class="diagram-caption">${kind==='voltage'?'Schematic; illustrative fixed-condition readings, not universal metal potentials.':'Schematic system, not an engineering design or reaction mechanism.'}</p>`,'CHEMICAL ENERGY → ELECTRICAL TRANSFER');}
